head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getUnmatchedXML]<br/>지정한 Row 범위에서 파라미터 조건에 만족하지 않는 Row 데이터를 XML 형태로 반환합니다.",
    "validation" : [
        "LinkedDataList 모듈에 필터/정렬이 적용된 상태를 기준으로 동작합니다.",
        "columnInfo(필수) 파라미터로 data 파라미터값과 비교하려는 Column 의 인덱스값을 설정합니다.",
        "Column 의 인덱스는 0 부터 시작합니다.",
        "data(필수) 파라미터로 columnInfo 파라미터의 Column 값과 비교하려는 텍스트를 설정합니다.",
        "exactMatch(선택) 파라미터로 data 파라미터값과 columnInfo 파라미터의 Column 값을 비교하는 방법을 true/false 로 설정합니다.",
        "exactMatch(선택) 파라미터로 미설정 또는 true 설정 시 data 파라미터값과 columnInfo 파라미터의 Column 값이 일치하는지 비교합니다. ('일치 비교' - Exact Match)",
        "exactMatch(선택) 파라미터로 false 설정 시 data 파라미터값이 columnInfo 파라미터의 Column 값에 포함되는지 비교합니다. ('부분 일치 비교' - Partial Match)",
        "값 비교 시 대소문자를 구분합니다.",
        "startRowIndex(선택) 파라미터로 data 파라미터값과 비교할 시작 Row 의 인덱스값을 숫자로 설정합니다.",
        "startRowIndex(선택) 파라미터 설정 시 Row 의 인덱스는 0 부터 시작하며 LinkedDataList 모듈의 필터/정렬 설정에 맞게 인덱스를 설정합니다.",
        "startRowIndex(선택) 파라미터를 생략하는 경우 0 으로 적용됩니다.",
        "lastRowIndex(선택) 파라미터로 data 파라미터값과 비교할 마지막 Row 의 다음 인덱스값을 숫자로 설정합니다. 설정한 인덱스값에 해당하는 Row 는 비교 대상에 포함되지 않으니 마지막 비교 대상 Row 의 다음 인덱스값을 설정합니다.",
        "lastRowIndex(선택) 파라미터 설정 시 Row 의 인덱스는 0 부터 시작하며 LinkedDataList 모듈의 필터/정렬 설정에 맞게 인덱스를 설정합니다.",
        "lastRowIndex(선택) 파라미터를 생략하는 경우 마지막 Row 까지 포함되도록 적용됩니다.",
        "반환값으로 필터/정렬이 적용된 상태를 기준으로 파라미터 조건에 만족하지 않는 Row 의 데이터를 XML 객체로 반환합니다.",
        "startRowIndex 파라미터의 Row 부터 lastRowIndex 파라미터의 이전 Row 까지를 대상으로 columnInfo 파라미터의 Column 값과 data 파라미터값이 exactMatch 파라미터의 비교 방법에 만족하지 않는 Row 데이터를 반환합니다.",
        "XML 은 LinkedDataList 모듈에 정렬이 적용된 순서대로 생성됩니다.",
        "반환된 객체의 xml 속성값은 원본 DataList 모듈의 baseNode 속성값이 Root 노드의 태그명으로, 반복되는 데이터 노드의 태그엔 repeatNode 속성값이 적용됩니다.",
        "Root 노드의 id 속성은 원본 DataLIst 모듈의 ID 가 설정됩니다.",
        "데이터 노드의 index 속성으로 필터/정렬이 적용되지 않은 원본 DataList 모듈의 Row 인덱스값이 설정됩니다.",
        "데이터 노드의 하위 노드로 원본 DataList 모듈의 Column ID 와 Column 값이 반복됩니다.",
        "데이터 노드는 'rowStatus' 를 마지막 하위 태그로 Row 의 상태값이 설정되며 'statusValue' 속성으로 상태코드값이 설정됩니다.",
        "Row 상태값에 관계없이 파라미터 조건에 만족하지 않는 Row 를 반환합니다.",
        "원본 DataList 모듈이 rowNumData=true 인 경우 반환값의 마지막 태그로 'rowNum' 이 추가되고 Row 의 순번(인덱스+1)값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }        

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	// target 생성
    $c.gcm.createOrginalDataList('rowNumData="true"');
    $c.gcm.createBasicLinkedDataList();

    // gridView 생성
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = gdl_org.insertRow();
    gdl_org.setRowData(insertIndex,["A","insert2","insert3","insert4"],true);
};



scwin.btn_deleteRow_onclick = function (e) {
    gdl_org.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    gdl_org.setCellData(2, "cat2", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    gdl_org.removeRow(3);
}



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter({type:"row", colIndex:"cat2", key:"A1", condition:"and"});
    target1.setColumnFilter({type:"row", colIndex:"cat2", key:"insert2", condition:"or"});
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("label", 1);
};



scwin.btn_getUnmatchedXML_onclick = function (e) {
    let rtn = '';
    let columnInfo = par_columnInfo.getText();
    let data = par_data.getValue();
    let exactMatch = par_exactMatch.getText();
    let startRowIndex = par_startRowIndex.getText();
    let lastRowIndex = par_lastRowIndex.getText();

    if (exactMatch == "true")
        exactMatch = true;
    else if (exactMatch == "false")
        exactMatch = false;
    else
        exactMatch = true;

    if (startRowIndex == "" && lastRowIndex == "")
        rtn = target1.getUnmatchedXML(Number(columnInfo), data, exactMatch);
    else if (lastRowIndex == "")
        rtn = target1.getUnmatchedXML(Number(columnInfo), data, exactMatch, Number(startRowIndex));
    else
        rtn = target1.getUnmatchedXML(Number(columnInfo), data, exactMatch, Number(startRowIndex), Number(lastRowIndex));


    const serializer = new XMLSerializer();
    let xmlString = serializer.serializeToString(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("result.xml: " + xmlString);  
};
